function expectationVal(v, digits=2, suffix=''){
  if(v===null || v===undefined || v==='') return '暂无数据';
  const n=Number(v);
  if(!Number.isFinite(n)) return '暂无数据';
  return n.toLocaleString('zh-CN',{maximumFractionDigits:digits}) + suffix;
}
